const input = $input.first().json;

const text = input.message_text || '';
const callbackData = input.callback_data || '';

let action = 'unknown';
let question_code = null;
let answer_value = null;

if (callbackData === 'sm:start') action = 'start';
else if (callbackData === 'sm:gps') action = 'gps';
else if (callbackData === 'sm:share') action = 'share';
else if (callbackData === 'sm:restart') action = 'restart';
else {
  const m = callbackData.match(/^sm:(q[1-5]):([1-4])$/);
  if (m) {
    action = 'answer';
    question_code = m[1];
    answer_value = m[2];
  } else if (input.intent === 'start' || text.startsWith('/start')) {
    action = 'open';
  } else if (text) {
    action = 'text';
  }
}

return [{
  json: {
    telegram_user_id: Number(input.external_id),
    external_id: String(input.external_id),
    chat_id: input.chat_id,
    first_name: input.first_name || 'Родитель',
    source: input.source || 'text',

    text,
    callback_data: callbackData,
    raw_content: text || callbackData || '',

    action,
    question_code,
    answer_value,

    start_param: input.start_param || null
  }
}];

