function inline(rows) {
  return {
    inline_keyboard: rows.map(row => row.map(button => ({
      text: button.text,
      callback_data: button.data
    })))
  };
}

function questionMessage(code) {
  const q = questions[code];
  const labels = buttonLabels[code];

  return {
    text: `${q.title}\n\n${q.text}`,
    reply_markup: inline([
      [{ text: labels['1'], data: `sm:${code}:1` }],
      [{ text: labels['2'], data: `sm:${code}:2` }],
      [{ text: labels['3'], data: `sm:${code}:3` }],
      [{ text: labels['4'], data: `sm:${code}:4` }]
    ])
  };
}
function stageToQuestion(stage) {
  return Object.keys(questions).find(k => questions[k].stage === stage) || null;
}

function calculateResult(nextAnswers) {
  const counts = { A: 0, B: 0, C: 0, D: 0 };
  const signals = [];

  for (const code of ['q1', 'q2', 'q3', 'q4', 'q5']) {
    const a = nextAnswers[code];
    if (!a) continue;

    counts[a.signal_code] = (counts[a.signal_code] || 0) + 1;
    signals.push({
      question_code: code,
      signal_code: a.signal_code,
      signal_label: a.signal_label,
      response_text: a.response_text
    });
  }

  if (counts.A >= 3) {
    return {
      result_type: 'route_emerging',
      result_title: 'Маршрут уже появился',
      dominant_signal: 'A',
      counts,
      signals
    };
  }

  if (counts.B >= 2) {
    return {
      result_type: 'external_launch',
      result_title: 'Маршрут зависит от внешнего запуска',
      dominant_signal: 'B',
      counts,
      signals
    };
  }

  return {
    result_type: 'open_water',
    result_title: 'Открытое плавание',
    dominant_signal: 'C_D',
    counts,
    signals
  };
}

