    old_stage: currentStage,
    new_stage: currentStage,
    referral_code: referralCode,
    bot_link: botLink
  });

  response = {
    text: `Если среди ваших знакомых есть родители, которые тоже задумываются о том, как проходит лето их ребёнка, — отправьте им эту карту.

${botLink}`,
    reply_markup: inline([[{ text: '🚀 Получить Summer GPS', data: 'sm:gps' }]])
  };
}

if (input.action === 'text' && currentStage && currentStage.startsWith('waiting_q')) {
  route = 'text_during_question';

  const expected = stageToQuestion(currentStage);
  const qm = questionMessage(expected);

  sql = eventSql('error', {
    event_name: 'summer_map_invalid_input',
    old_stage: currentStage,
    new_stage: currentStage,
    text: input.text,
    reason: 'text_instead_of_button'
  });

  response = {
    text: `Выберите один из вариантов кнопками ниже.

${qm.text}`,
    reply_markup: qm.reply_markup
  };
}

return [{
  json: {
    ...input,
    current_stage: currentStage,
    route,
    persist_sql: sql,
    persist_params: [],
    response_text: response.text,
    reply_markup: response.reply_markup
  }
}];

const triggerItem = $('TG_Trigger').first().json;

const isCallback = !!triggerItem.callback_query;

const msg = isCallback
  ? triggerItem.callback_query.message
  : triggerItem.message;

const from = isCallback
  ? triggerItem.callback_query.from
  : triggerItem.message.from;

const chat = msg.chat;

let messageText = '';

if ($json.route === 'voice') {
  messageText = $json.text || '';
} else {
  messageText =
    triggerItem.message?.text ||
    triggerItem.callback_query?.data ||
    '';
}

return [{
  json: {
    external_id: String(from.id),
    first_name: from.first_name || 'Родитель',
    chat_id: chat.id,

    message_text: messageText,
    callback_data: triggerItem.callback_query?.data || '',

    start_param:
      triggerItem.message?.text?.startsWith('/start ')
        ? triggerItem.message.text.split(' ')[1]
        : null,

    intent:
      triggerItem.message?.text?.startsWith('/start')
        ? 'start'
        : isCallback
          ? 'callback'
          : 'message',

    source:
      $json.route === 'voice'
        ? 'voice'
        : isCallback
          ? 'callback'
          : 'text'
  }
}];

const summerMap = $('SYS_ProcessSummerMap').first().json;
const replyMarkup = summerMap.reply_markup || {};
const inlineKeyboard = Array.isArray(replyMarkup.inline_keyboard)
  ? replyMarkup.inline_keyboard
  : [];

const firstCallback =
  inlineKeyboard?.[0]?.[0]?.callback_data || '';

let screen = 'fallback';

if (summerMap.route === 'gps') {
  screen = 'gps';
}
else if (summerMap.route === 'answer_result_offer' || summerMap.route === 'result') {
  screen = 'result';
}
else if (firstCallback === 'sm:start') {
  screen = 'intro';
}
else if (firstCallback.startsWith('sm:q1:')) {
  screen = 'q1';
}
else if (firstCallback.startsWith('sm:q2:')) {
  screen = 'q2';
}
else if (firstCallback.startsWith('sm:q3:')) {
  screen = 'q3';
}
else if (firstCallback.startsWith('sm:q4:')) {
  screen = 'q4';
}
else if (firstCallback.startsWith('sm:q5:')) {
  screen = 'q5';
}
else if (firstCallback === 'sm:gps') {
  screen = 'result';
}
else if (firstCallback === 'sm:share') {
  screen = 'share';
}
else if (summerMap.current_stage === 'completed') {
  screen = 'result';
}
else if (summerMap.route === 'share') {
  screen = 'share';
}

return [{
  json: {
    chat_id: summerMap.chat_id,
    text: summerMap.response_text,

    route: summerMap.route,
    current_stage: summerMap.current_stage,

    screen,
    first_callback: firstCallback,

    reply_markup: replyMarkup,
    reply_markup_string: JSON.stringify(replyMarkup),

    debug: {
      has_reply_markup: !!summerMap.reply_markup,
      has_inline_keyboard: inlineKeyboard.length > 0,
      keyboard_rows: inlineKeyboard.length,
      first_row: inlineKeyboard[0] || null
    }
  }
}];
